"""olay_bildirimi_triyaj - Files'a dusen olay bildirim formunu triyaj akisindan gecirir.

Tetikleyici: Event bus kurali (Files > "A file is uploaded", yol oneki olay-bildirimleri/).
Girdi: olay zarfi; event["data"] icinde object_id, name, path bulunur.
Cikti: triyaj-sonuclari/ klasorune <form>-triyaj-<zaman>.json; form metni "Olay Bildirimleri"
bilgi tabanina alinir (kisisel veri KB'nin PII profilinde maskelenir).

Akis ve bilgi tabani kimlikle cagrilir (politika adla cozumlemeye izin vermez). Gerekirse
Configuration > Environment variables: LAB_PROJECT, LAB_ENV, TRIYAJ_FLOW_ID, SONUC_KLASORU, OLAY_KB_ID.
"""
import json
import os
import datetime as dt

LAB_PROJECT = os.environ.get("LAB_PROJECT", "Hasta Guvenligi")
LAB_ENV = os.environ.get("LAB_ENV", "dev")
TRIYAJ_FLOW_ID = os.environ.get("TRIYAJ_FLOW_ID", "01a133e6-1e9f-7dfb-9d20-5b9952426ed5")
SONUC_KLASORU = os.environ.get("SONUC_KLASORU", "triyaj-sonuclari")
OLAY_KB_ID = os.environ.get("OLAY_KB_ID", "01a13089-67b2-7e66-a325-afa1b2e86daa")


def _scoped():
    """Files (proje, ortam) kapsamlidir; gerekiyorsa istemciyi projeye baglar."""
    scopes = howlet.drive.scopes()  # noqa: F821  (calisma zamaninda enjekte edilir)
    if not scopes:
        return howlet  # noqa: F821
    pick = next((s for s in scopes
                 if str(s.get("project_name", "")).strip().lower() == LAB_PROJECT.lower()
                 and str(s.get("environment_slug", "")) == LAB_ENV), scopes[0])
    return howlet.with_scope(project_id=pick["project_id"], environment=pick["environment_slug"])  # noqa: F821


def _folder_by_name(h, name):
    root = h.drive.folder("root") or {}
    for child in root.get("children") or []:
        if str(child.get("name", "")).lower() == name.lower():
            return child["id"]
    return h.drive.create_folder({"name": name})["id"]


def handler(event, context=None):
    data = (event.get("data") if isinstance(event, dict) else None) or event or {}
    object_id = data.get("object_id")
    name = data.get("name") or "olay-bildirimi.txt"
    if not object_id:
        return {"atlandi": "olayda object_id yok", "olay": event}
    if "olay-bildirimleri" not in str(data.get("path", "")):
        return {"atlandi": "olay-bildirimleri klasoru disinda", "yol": data.get("path")}

    h = _scoped()
    metin = h.drive.download(object_id).decode("utf-8", errors="replace")

    sonuc = h.flows.run(TRIYAJ_FLOW_ID, {"message": metin}) or {}
    durum, cikti = sonuc.get("status"), sonuc.get("final_output")
    if durum == "blocked":
        triyaj = {"engellendi": True, "mesaj": cikti}
    else:
        try:
            triyaj = json.loads(cikti) if isinstance(cikti, str) else cikti
        except ValueError:
            triyaj = {"ham_cikti": cikti}

    zaman = dt.datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
    kok = name.rsplit(".", 1)[0]
    onek = "KRITIK-" if str((triyaj or {}).get("oncelik", "")) == "Kritik" else ""
    dosya = f"{onek}{kok}-triyaj-{zaman}.json"
    h.drive.upload(_folder_by_name(h, SONUC_KLASORU), dosya,
                   json.dumps(triyaj, ensure_ascii=False, indent=2).encode("utf-8"),
                   content_type="application/json")

    h.kb.ingest(OLAY_KB_ID, name, metin)
    return {"form": name, "akis_durumu": durum, "triyaj": triyaj,
            "sonuc_dosyasi": dosya, "kb": "kuyruga alindi"}
